const struct sf_desc *sf_desc_for_game(u8 game_id)
{
	unsigned i;

	for (i = 0; i < sizeof(sf_descs) / sizeof(sf_descs[0]); i++) {
		if (sf_descs[i].game_id == game_id) return &sf_descs[i];
	}
	return NULL;
}
